/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Exports
 *   Types: CatalogCreditSubjectType, CatalogCreditRole, AttributionStatus, CatalogCredit,
 *          ArtistAlbumCreditSection
 *   Classes: CatalogCreditValidationError
 *   Functions: normalizeJoinPhrase, storedJoinPhrase, createCatalogCreditId, migratedCatalogCreditId,
 *              creditsForLegacyArtistIds, mergeLegacyArtistIdsIntoCredits, normalizeCatalogCredits,
 *              normalizeStoredCatalogCredits, invalidStoredJoinPhraseCreditIds, withoutJoinPhrase,
 *              retainStoredJoinPhrases, inheritedAlbumPrimaryCredits, validateAttribution,
 *              legacyTrackArtistIdsFromCredits, legacyAlbumArtistIdsFromCredits, classifyArtistAlbumCredit
 *   Constants: catalogCreditSubjectTypes, catalogCreditRoles, maximumJoinPhraseLength
 * Internal
 *   Functions: normalizedSubjectType, normalizedRole, normalizedSubjectId, normalizedCreditId,
 *              normalizeCreditList
 *   Constants: artistRoles, organizationRoles, creditIdPattern, objectIdPattern, loneSurrogatePattern,
 *              forbiddenJoinPhrasePattern, visibleCharacterPattern, fusingEdgePattern
 * @end-catalog */

import { createHash, randomUUID } from 'node:crypto';

export const catalogCreditSubjectTypes = ['artist', 'organization'] as const;
export type CatalogCreditSubjectType = typeof catalogCreditSubjectTypes[number];

export const catalogCreditRoles = [
    'primary',
    'featured',
    'performer',
    'composer',
    'producer',
    'remixer',
    'label',
    'publisher',
    'distributor',
    'presenter',
    'legacyUnspecified'
] as const;
export type CatalogCreditRole = typeof catalogCreditRoles[number];
export type AttributionStatus = 'documented' | 'unknown';

export interface CatalogCredit {
    creditId: string;
    subjectType: CatalogCreditSubjectType;
    subjectId: string;
    role: CatalogCreditRole;
    order: number;
    /**
     * Presentation-only text joining this Credit's name to the next byline name; absent means
     * `, `. Never sent to clients. The key is omitted, never undefined, when no phrase is set,
     * so phrase-free Credits keep their stored bytes and revisions.
     */
    joinPhrase?: string;
}

/** Longest accepted join phrase, in UTF-16 code units after NFC normalization. */
export const maximumJoinPhraseLength = 16;

const artistRoles = new Set<CatalogCreditRole>([
    'primary',
    'featured',
    'performer',
    'composer',
    'producer',
    'remixer',
    'legacyUnspecified'
]);
const organizationRoles = new Set<CatalogCreditRole>([
    'label',
    'publisher',
    'distributor',
    'presenter',
    'legacyUnspecified'
]);
const creditIdPattern = /^[A-Za-z0-9_-]{8,100}$/;
const objectIdPattern = /^[0-9a-f]{24}$/;
const loneSurrogatePattern = /[\ud800-\udbff](?![\udc00-\udfff])|(?<![\ud800-\udbff])[\udc00-\udfff]/;
// Controls, invisible formatting characters, line or paragraph separators, private-use and
// unassigned code points (noncharacters included), and characters that render as blanks: the
// grapheme joiner, the Hangul and Khmer fillers, and the braille blank.
const forbiddenJoinPhrasePattern =
    /[\p{Cc}\p{Cf}\p{Zl}\p{Zp}\p{Co}\p{Cn}\u034F\u115F\u1160\u17B4\u17B5\u2800\u3164\uFFA0]/u;
// A character that renders by itself: not whitespace, a combining mark, or default-ignorable.
const visibleCharacterPattern = /[^\p{White_Space}\p{M}\p{Default_Ignorable_Code_Point}]/u;
// Edges that would fuse with the neighboring name into one grapheme: a leading mark (variation
// selectors included), emoji modifier, regional indicator, or Hangul medial or final jamo, and
// a trailing regional indicator or Hangul initial jamo.
const fusingEdgePattern =
    /^[\p{M}\p{Emoji_Modifier}\p{Regional_Indicator}\u1160-\u11FF\uD7B0-\uD7FF]|[\p{Regional_Indicator}\u1100-\u115F\uA960-\uA97F]$/u;

export class CatalogCreditValidationError extends Error {
    readonly statusCode = 400;
    readonly code = 'catalog_credit_invalid';

    constructor(message: string) {
        super(message);
    }
}

const normalizedSubjectType = (value: unknown): CatalogCreditSubjectType => {
    if (value === 'artist' || value === 'organization') return value;
    throw new CatalogCreditValidationError('Credit subjectType must be artist or organization.');
};

const normalizedRole = (value: unknown): CatalogCreditRole => {
    if (catalogCreditRoles.includes(value as CatalogCreditRole)) return value as CatalogCreditRole;
    throw new CatalogCreditValidationError('Credit role is not supported.');
};

const normalizedSubjectId = (value: unknown) => {
    const subjectId = String(value ?? '').trim().toLowerCase();
    if (!objectIdPattern.test(subjectId)) {
        throw new CatalogCreditValidationError('Credit subjectId must be a canonical ID.');
    }
    return subjectId;
};

const normalizedCreditId = (value: unknown) => {
    const creditId = String(value ?? '').trim();
    if (!creditIdPattern.test(creditId)) {
        throw new CatalogCreditValidationError('Credit creditId is invalid.');
    }
    return creditId;
};

/**
 * Strictly validates one join phrase for a write; undefined means absent. The phrase is NFC
 * normalized, must contain a visible character, must not contain a control, format, line or
 * paragraph separator, private-use, unassigned or blank-rendering character or a lone
 * surrogate, must not begin or end with a character that fuses with the neighboring name, and
 * fits within 16 UTF-16 units. Surrounding spaces are kept because they are part of the
 * presentation (` & ` versus `、`).
 */
export const normalizeJoinPhrase = (value: unknown): string | undefined => {
    if (value === undefined) return undefined;
    const invalid = () => new CatalogCreditValidationError('Credit joinPhrase is invalid.');
    if (typeof value !== 'string' || loneSurrogatePattern.test(value)) throw invalid();
    const phrase = value.normalize('NFC');
    if (forbiddenJoinPhrasePattern.test(phrase)
        || fusingEdgePattern.test(phrase)
        || !visibleCharacterPattern.test(phrase)
        || phrase.length > maximumJoinPhraseLength) {
        throw invalid();
    }
    return phrase;
};

/** Reads a stored join phrase; one that fails validation is dropped, so the byline shows `, `. */
export const storedJoinPhrase = (value: unknown): string | undefined => {
    try {
        return normalizeJoinPhrase(value);
    } catch {
        return undefined;
    }
};

/** Creates an opaque stable ID for new interactive Credits. */
export const createCatalogCreditId = () => randomUUID().replace(/-/g, '_');

/** Creates a deterministic Credit ID for an idempotent legacy migration. */
export const migratedCatalogCreditId = (
    ownerType: 'album' | 'audioTrack',
    ownerId: string,
    subjectType: CatalogCreditSubjectType,
    subjectId: string,
    role: CatalogCreditRole
) => createHash('sha256')
    .update(`${ownerType}\0${ownerId}\0${subjectType}\0${subjectId}\0${role}`, 'utf8')
    .digest('base64url')
    .slice(0, 32);

/** Builds deterministic Credits for a legacy artist-ID write during the compatibility window. */
export const creditsForLegacyArtistIds = (
    ownerType: 'album' | 'audioTrack',
    ownerId: string,
    artistIds: readonly string[],
    role: Extract<CatalogCreditRole, 'primary' | 'legacyUnspecified'>
) => normalizeCatalogCredits([...new Set(artistIds.map((id) => id.trim().toLowerCase()))]
    .filter(Boolean)
    .map((subjectId, order) => ({
        creditId: migratedCatalogCreditId(ownerType, ownerId, 'artist', subjectId, role),
        subjectType: 'artist',
        subjectId,
        role,
        order
    })));

/** Applies a legacy artist-ID edit without discarding Organization or known-role Credits. */
export const mergeLegacyArtistIdsIntoCredits = (
    ownerType: 'album' | 'audioTrack',
    ownerId: string,
    existingValue: unknown,
    artistIds: readonly string[]
) => {
    // Read tolerantly so an invalid stored phrase cannot block the edit; retained Credits keep
    // their valid phrases.
    const existing = Array.isArray(existingValue) ? normalizeStoredCatalogCredits(existingValue) : [];
    const requestedArtistIds = [...new Set(artistIds.map((id) => id.trim().toLowerCase()))];
    const retainedOrganizations = existing.filter((credit) => credit.subjectType === 'organization');
    const retainedArtists = existing.filter((credit) => credit.subjectType === 'artist'
        && requestedArtistIds.includes(credit.subjectId));
    const representedArtists = new Set(retainedArtists.map((credit) => credit.subjectId));
    const addedArtists = requestedArtistIds
        .filter((subjectId) => !representedArtists.has(subjectId))
        .map((subjectId) => ({
            creditId: migratedCatalogCreditId(
                ownerType,
                ownerId,
                'artist',
                subjectId,
                'legacyUnspecified'
            ),
            subjectType: 'artist' as const,
            subjectId,
            role: 'legacyUnspecified' as const,
            order: 0
        }));
    return normalizeCatalogCredits([
        ...retainedArtists,
        ...addedArtists,
        ...retainedOrganizations
    ]);
};

/** Validates one ordered Credit list, reading each join phrase with the given policy. */
const normalizeCreditList = (
    value: unknown,
    maximumCredits: number,
    phraseOf: (value: unknown) => string | undefined
): CatalogCredit[] => {
    if (!Array.isArray(value)) {
        throw new CatalogCreditValidationError('Credits must be an array.');
    }
    if (value.length > maximumCredits) {
        throw new CatalogCreditValidationError(`No more than ${maximumCredits} Credits are allowed.`);
    }

    const normalized = value.map((raw, index) => {
        if (!raw || typeof raw !== 'object' || Array.isArray(raw)) {
            throw new CatalogCreditValidationError(`Credit ${index + 1} must be an object.`);
        }
        const source = raw as Record<string, unknown>;
        const subjectType = normalizedSubjectType(source.subjectType);
        const role = normalizedRole(source.role);
        const permittedRoles = subjectType === 'artist' ? artistRoles : organizationRoles;
        if (!permittedRoles.has(role)) {
            throw new CatalogCreditValidationError(
                `Credit role ${role} is not valid for ${subjectType} subjects.`
            );
        }
        const creditId = normalizedCreditId(source.creditId);
        const subjectId = normalizedSubjectId(source.subjectId);
        // Read after the structural fields so their error precedence is unchanged.
        const joinPhrase = phraseOf(source.joinPhrase);
        return {
            creditId,
            subjectType,
            subjectId,
            role,
            order: index,
            ...(joinPhrase === undefined ? {} : { joinPhrase })
        } satisfies CatalogCredit;
    });

    const seenCreditIds = new Set<string>();
    const seenRelationships = new Set<string>();
    for (const credit of normalized) {
        if (seenCreditIds.has(credit.creditId)) {
            throw new CatalogCreditValidationError('Credit IDs must be unique within one item.');
        }
        seenCreditIds.add(credit.creditId);
        const relationship = `${credit.subjectType}:${credit.subjectId}:${credit.role}`;
        if (seenRelationships.has(relationship)) {
            throw new CatalogCreditValidationError('Duplicate subject and role Credits are not allowed.');
        }
        seenRelationships.add(relationship);
    }
    return normalized;
};

/**
 * Validates and canonicalizes one complete ordered Credit list for a write, including each
 * join phrase. Unknown fields are dropped and key order is fixed, so two normalized lists are
 * JSON-equal exactly when they hold the same Credits and phrases.
 */
export const normalizeCatalogCredits = (
    value: unknown,
    maximumCredits: number = 50
): CatalogCredit[] => normalizeCreditList(value, maximumCredits, normalizeJoinPhrase);

/**
 * Reads a stored Credit list with the same structural checks but drops each join phrase that
 * fails validation instead of rejecting the list, so a bad phrase never hides attribution.
 */
export const normalizeStoredCatalogCredits = (
    value: unknown,
    maximumCredits: number = 50
): CatalogCredit[] => normalizeCreditList(value, maximumCredits, storedJoinPhrase);

/** Lists the valid creditIds of stored Credits whose join phrase is present but invalid. */
export const invalidStoredJoinPhraseCreditIds = (value: unknown): string[] => {
    if (!Array.isArray(value)) return [];
    return value.flatMap((raw): string[] => {
        if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return [];
        const source = raw as Record<string, unknown>;
        if (source.joinPhrase === undefined) return [];
        try {
            normalizeJoinPhrase(source.joinPhrase);
            return [];
        } catch {
            const creditId = String(source.creditId ?? '').trim();
            return creditIdPattern.test(creditId) ? [creditId] : [];
        }
    });
};

/** Returns the Credit's five structural fields in canonical key order, without a join phrase. */
export const withoutJoinPhrase = (credit: CatalogCredit): CatalogCredit => ({
    creditId: credit.creditId,
    subjectType: credit.subjectType,
    subjectId: credit.subjectId,
    role: credit.role,
    order: credit.order
});

/**
 * Carries stored join phrases into a proposed list by creditId for an editor that cannot see
 * phrases yet. Elements that are not objects with a known string creditId pass through
 * unchanged for normalization to judge. S1 only: S2b replaces this with explicit phrase editing.
 */
export const retainStoredJoinPhrases = (
    proposed: unknown,
    stored: readonly CatalogCredit[]
): unknown => {
    if (!Array.isArray(proposed)) return proposed;
    const phrases = new Map(stored.flatMap((credit): Array<[string, string]> =>
        credit.joinPhrase === undefined ? [] : [[credit.creditId, credit.joinPhrase]]));
    return proposed.map((element) => {
        if (!element || typeof element !== 'object' || Array.isArray(element)) return element;
        const creditId = (element as Record<string, unknown>).creditId;
        const joinPhrase = typeof creditId === 'string' ? phrases.get(creditId.trim()) : undefined;
        return joinPhrase === undefined ? element : { ...element, joinPhrase };
    });
};

/**
 * Materializes a new MediaTrack's inherited Album primary-Artist Credits in Album order with
 * their valid join phrases. A phrase is kept only when the Album Credit right after it is also
 * inherited: a phrase joins its name to the next stored Credit, so copying it past a skipped
 * Credit would join two inherited names with text meant for another one (for example `feat.`
 * written before a featured Artist would then precede the next primary Artist). The last
 * inherited phrase is therefore always cleared.
 */
export const inheritedAlbumPrimaryCredits = (
    audioTrackId: string,
    albumCredits: unknown
): CatalogCredit[] => {
    if (!Array.isArray(albumCredits)) return [];
    const isInherited = (raw: any) => raw?.subjectType === 'artist' && raw?.role === 'primary';
    return albumCredits.flatMap((raw: any, index): CatalogCredit[] => {
        if (!isInherited(raw)) return [];
        const joinPhrase = isInherited(albumCredits[index + 1]) ? storedJoinPhrase(raw.joinPhrase) : undefined;
        return [{
            creditId: migratedCatalogCreditId(
                'audioTrack', audioTrackId, 'artist', String(raw.subjectId), 'primary'
            ),
            subjectType: 'artist',
            subjectId: String(raw.subjectId),
            role: 'primary',
            order: 0,
            ...(joinPhrase === undefined ? {} : { joinPhrase })
        }];
    });
};

/** Enforces the publication invariant without manufacturing an unknown subject. */
export const validateAttribution = (
    status: unknown,
    credits: readonly CatalogCredit[]
): AttributionStatus => {
    if (status !== 'documented' && status !== 'unknown') {
        throw new CatalogCreditValidationError('attributionStatus must be documented or unknown.');
    }
    if (status === 'documented' && credits.length === 0) {
        throw new CatalogCreditValidationError('Documented attribution requires at least one Credit.');
    }
    if (status === 'unknown' && credits.length > 0) {
        throw new CatalogCreditValidationError('Unknown attribution cannot contain documented Credits.');
    }
    return status;
};

/** Projects the ordered legacy MediaTrack Artist IDs from visible Artist Credits. */
export const legacyTrackArtistIdsFromCredits = (credits: readonly CatalogCredit[]) => [
    ...new Set(credits
        .filter((credit) => credit.subjectType === 'artist')
        .sort((left, right) => left.order - right.order)
        .map((credit) => credit.subjectId))
];

/** Projects only formal Album ownership for clients that render albumIds as Discography. */
export const legacyAlbumArtistIdsFromCredits = (credits: readonly CatalogCredit[]) => [
    ...new Set(credits
        .filter((credit) => credit.subjectType === 'artist' && credit.role === 'primary')
        .sort((left, right) => left.order - right.order)
        .map((credit) => credit.subjectId))
];

export type ArtistAlbumCreditSection =
    | 'discography'
    | 'collaborations'
    | 'appearsOn'
    | 'credits'
    | null;

/** Classifies one Album once for an Artist using the canonical precedence rule. */
export const classifyArtistAlbumCredit = (
    artistId: string,
    albumCredits: readonly CatalogCredit[],
    soundtrackCredits: readonly CatalogCredit[]
): ArtistAlbumCreditSection => {
    const normalizedArtistId = normalizedSubjectId(artistId);
    const albumRoles = new Set(albumCredits
        .filter((credit) => credit.subjectType === 'artist' && credit.subjectId === normalizedArtistId)
        .map((credit) => credit.role));
    if (albumRoles.has('primary')) return 'discography';
    if (albumRoles.has('featured')) return 'collaborations';

    const trackRoles = new Set(soundtrackCredits
        .filter((credit) => credit.subjectType === 'artist' && credit.subjectId === normalizedArtistId)
        .map((credit) => credit.role));
    if (['primary', 'featured', 'performer', 'legacyUnspecified']
        .some((role) => trackRoles.has(role as CatalogCreditRole))) {
        return 'appearsOn';
    }
    if (['composer', 'producer', 'remixer']
        .some((role) => albumRoles.has(role as CatalogCreditRole)
            || trackRoles.has(role as CatalogCreditRole))) {
        return 'credits';
    }
    return null;
};
